<?php
require_once __DIR__.'/../includes/cost_overview_data.php';
function verify($ok,$message){if(!$ok)throw new RuntimeException($message);}
$rows=overview_test_rows();verify(count($rows)===96,'96 rows preserved');verify(count(array_unique(array_column($rows,'id')))===96,'Unique records');
$a=overview_period($rows,'2026-01-01','2026-12-31','2026-12-31');$eligible=array_values(array_filter($rows,fn($r)=>str_starts_with($r['date'],'2026')));
$cost=array_sum(array_map(fn($r)=>$r['fuel']+$r['maintenance']+$r['toll']+($r['other']??0),$eligible));$funded=array_values(array_filter($eligible,fn($r)=>$r['funding']!==null));$funding=array_sum(array_column($funded,'funding'));$remaining=array_sum(array_map(fn($r)=>$r['funding']-($r['fuel']+$r['maintenance']+$r['toll']+($r['other']??0)),$funded));
verify($a['count']===48,'All completed vehicles');verify(count(array_unique(array_column($eligible,'vehicle')))>1,'Fleet-wide');verify($a['cost']===$cost,'Independent costs');verify($a['allowance']===$funding,'Only approved allowance amounts');verify($a['remaining']===$remaining,'Sum per-funded-trip balances, not funding minus all fleet expenses');verify($a['average']===$cost/48,'Completed cost denominator');
foreach(['cost','allowance','remaining','fuel','maintenance','toll'] as $key)verify(array_sum(array_column($a['months'],$key))===$a[$key],'Monthly reconciliation '.$key);
verify(count(array_filter($a['rows'],fn($r)=>$r['remaining']!==null&&$r['remaining']<0))>0,'Individual shortfalls retained');verify(count(array_filter($a['rows'],fn($r)=>$r['funding']===null&&$r['remaining']===null))>0,'Unfunded stays incomparable');
foreach($a['rows'] as $r){verify($r['variance']===$r['cost']-$r['estimate'],'Separate estimate variance');if($r['funding']!==null)verify($r['remaining']===$r['funding']-$r['cost'],'Separate funding balance');}
$test=$eligible[0];$test['funding']=999999;$test['funding_status']='Pending';$p=overview_period([$test],$test['date'],$test['date'],'2026-12-31');verify($p['allowance']===null&&$p['remaining']===null,'Pending funding excluded');
$test['funding_status']='Rejected';verify(overview_period([$test],$test['date'],$test['date'],'2026-12-31')['allowance']===null,'Rejected excluded');
$test['funding_status']='Funding Confirmed';$test['expense_complete']=false;$p=overview_period([$test],$test['date'],$test['date'],'2026-12-31');verify($p['allowance']===999999&&$p['remaining']===null&&$p['rows'][0]['variance']===null,'Incomplete cost not balanced or compared');
$test['status']='In Progress';$p=overview_period([$test],$test['date'],$test['date'],'2026-12-31');verify($p['count']===0&&$p['average']===null&&$p['allowance']===999999,'Ongoing allowance, not completed denominator');
$test['status']='Cancelled';verify(overview_period([$test],$test['date'],$test['date'],'2026-12-31')['scope_count']===0,'Cancelled excluded');
$test['status']='Completed';$test['cost_recorded']=false;$test['expense_complete']=false;$test['fuel']=null;$test['maintenance']=null;$test['toll']=null;$test['other']=null;$p=overview_period([$test],$test['date'],$test['date'],'2026-12-31');verify($p['cost']===null&&$p['average']===null&&$p['remaining']===null,'Missing expenses never zero');
$duplicates=array_merge($rows,[$rows[0]]);verify(overview_period($duplicates,'2025-01-01','2026-12-31','2026-12-31')['scope_count']===96,'No duplicate expenses');
$current=overview_period($rows,'2026-01-01','2026-12-31','2026-10-15');verify($current['count']===38,'Future test records excluded');
foreach([['2023-01-01','2023-12-31'],['2027-01-01','2027-12-31']] as [$from,$to]){verify(overview_period($rows,$from,$to,'2026-10-15')['cost']===null,'Missing years unavailable');}
verify(overview_previous_date('2024-02-29')==='2023-02-28','Leap date');verify(overview_change(10,0)===null,'Zero baseline');
foreach([['2020-01-01','2026-12-31'],['2025-01-01','2026-12-31']] as [$from,$to]){$plan=overview_date_plan($from,$to,'2026-10-15');$p=overview_period($rows,$plan['from'],$plan['to'],'2026-10-15');$before=overview_period($rows,$plan['previous_from'],$plan['previous_to'],'2026-10-15');$series=overview_bucket_series($p,$plan['buckets']);verify(count($series)===12,'Endpoint aligned monthly');verify(abs(array_sum(array_column($series,'cost'))*100-$p['cost'])<.001,'Chart cost matches KPI');verify(abs(array_sum(array_column($series,'allowance'))*100-$p['allowance'])<.001,'Chart allowance matches KPI');verify(substr($plan['from'],0,4)===substr($to,0,4),'Endpoint behavior retained');}
$insights=overview_insights($current,overview_period($rows,'2025-01-01','2025-10-15'));verify(count($insights)===4,'Four rule-based cards');verify(!preg_match('/revenue|profit|passenger/i',json_encode($insights)),'No revenue/profit insight dependency');
echo "Cost Overview allowance/cost financial checks passed: fleet totals, trip balances, shortfalls, incomplete/pending/unfunded cases, monthly reconciliation, year filters and future exclusion.\n";
